\set ON_ERROR_STOP on
SELECT public.report_test_assert(current_database()='book_reports_test','disposable database');
SET ROLE anon;
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_access()$q$,'permission denied');
SELECT public.report_expect_error($q$SELECT * FROM public.book_reports_v2$q$,'permission denied');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
SET ROLE authenticated;
SELECT public.report_test_assert((public.book_reports_v2_access()->>'staff')::boolean=false,'reader is not staff');
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_queue()$q$,'Staff access');
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_submit(gen_random_uuid(),'hidden','other','Detailed explanation')$q$,'not available');
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_submit(gen_random_uuid(),'draft','other','Detailed explanation')$q$,'not available');
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-1','other','short')$q$,'10');
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-1','invalid','Detailed explanation')$q$,'reason');
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-1','improper_tags','Detailed explanation')$q$,'tags');
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-1','other','Detailed explanation','secret-draft')$q$,'available chapter');
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-1','other','Detailed explanation','','','javascript:alert(1)')$q$,'supporting link');
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-1','other','Detailed explanation','','','https://user:pass@example.org')$q$,'supporting link');
SELECT public.book_reports_v2_submit('10000000-0000-0000-0000-000000000001','book-1','improper_tags','Missing a warning for the injury.','chapter-one','Graphic injuries','https://example.org');
SELECT public.report_test_assert((public.book_reports_v2_submit('10000000-0000-0000-0000-000000000001','book-1','improper_tags','Missing a warning for the injury.','chapter-one','Graphic injuries')->>'existing')::boolean=false,'same request is idempotent');
SELECT public.report_test_assert((public.book_reports_v2_submit(gen_random_uuid(),'book-1','other','A second detailed concern.')->>'existing')::boolean=true,'one open report per book');
SELECT set_config('test.report_id',public.book_reports_v2_own('book-1')->>'id',false);
SELECT public.report_test_assert((SELECT count(*) FROM public.book_reports_v2)=0,'reader cannot read raw rows');
SELECT public.report_test_assert((SELECT count(*) FROM public.book_report_events_v2)=0,'reader cannot read staff history');
SELECT public.report_expect_error($q$INSERT INTO public.book_reports_v2(request_id,book_id,book_title,author_label,reporter_id,reason,explanation) VALUES(gen_random_uuid(),'book-2','Forged','Forged',auth.uid(),'other','Detailed explanation')$q$,'permission denied');
SELECT public.report_expect_error($q$UPDATE public.book_reports_v2 SET status='resolved'$q$,'permission denied');
SELECT public.book_reports_v2_followup(current_setting('test.report_id')::uuid,'Additional information for staff.','20000000-0000-0000-0000-000000000001');
SELECT public.book_reports_v2_followup(current_setting('test.report_id')::uuid,'Additional information for staff.','20000000-0000-0000-0000-000000000001');
RESET ROLE;
SELECT public.report_test_assert((SELECT count(*) FROM public.book_reports_v2)=1,'submission retries do not duplicate');
SELECT public.report_test_assert((SELECT count(*) FROM public.book_report_events_v2 WHERE kind='followup')=1,'follow-up retry idempotent');
SELECT public.report_test_assert((SELECT book_title FROM public.book_reports_v2 LIMIT 1)='Book 1','server stores canonical title');
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000004';
SET ROLE authenticated;
SELECT public.report_test_assert(public.book_reports_v2_own('book-1') IS NULL,'other reader cannot fetch receipt');
SELECT public.report_expect_error(format('SELECT public.book_reports_v2_followup(%L,''Another reader cannot append.'',gen_random_uuid())',current_setting('test.report_id')),'not found');
SELECT public.report_expect_error(format('SELECT public.book_reports_v2_detail(%L)',current_setting('test.report_id')),'Staff access');
SELECT public.report_expect_error(format('SELECT public.book_reports_v2_review(%L,''resolved'',''Forged closure'',2)',current_setting('test.report_id')),'Staff access');
SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-1','suspected_ai','Here is the concern about this work.');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
SET ROLE authenticated;
SELECT public.report_test_assert((public.book_reports_v2_access()->>'staff')::boolean,'moderator access');
SELECT public.report_test_assert((public.book_reports_v2_queue()->>'total')::int=1,'reports grouped by book');
SELECT public.report_test_assert((public.book_reports_v2_queue()->'items'->0->>'reportCount')::int=2,'distinct reporters retained');
SELECT public.report_test_assert((public.book_reports_v2_book('book-1')->>'total')::int=2,'all book reports available');
SELECT public.report_test_assert(public.book_reports_v2_detail(current_setting('test.report_id')::uuid)->'reporter'->>'id'='00000000-0000-0000-0000-000000000003','staff can identify reporter');
SELECT public.report_expect_error(format('SELECT public.book_reports_v2_review(%L,''resolved'',''tiny'',2)',current_setting('test.report_id')),'10 characters');
SELECT public.book_reports_v2_review(current_setting('test.report_id')::uuid,'under_review','Private staff note: verifying chapter.',2);
SELECT public.report_expect_error(format('SELECT public.book_reports_v2_review(%L,''resolved'',''Stale review should fail'',2)',current_setting('test.report_id')),'changed');
SELECT public.book_reports_v2_review(current_setting('test.report_id')::uuid,'resolved','Warnings corrected after review.',3);
SELECT public.report_test_assert((SELECT count(*) FROM public.book_report_events_v2 WHERE kind='review')=2,'review audit retained');
SELECT public.report_test_assert((public.book_reports_v2_queue('resolved')->>'total')::int=1,'status filters');
SELECT public.report_test_assert((public.book_reports_v2_queue('open','improper_tags')->>'total')::int=0,'combined filters');
SELECT public.report_test_assert((SELECT count(*) FROM public.book_reports_v2)=2,'staff RLS permits read');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
SET ROLE authenticated;
SELECT public.report_test_assert(public.book_reports_v2_own('book-1') IS NULL,'closed report no longer blocks new report');
SELECT public.report_test_assert((SELECT count(*) FROM public.book_report_events_v2)=0,'private notes stay hidden');
SELECT public.report_expect_error(format('SELECT public.book_reports_v2_followup(%L,''New information after closure'',gen_random_uuid())',current_setting('test.report_id')),'closed');
SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-1','other','A new concern after closure.');
SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-2','other','A detailed concern for book two.');
SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-3','other','A detailed concern for book three.');
SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-4','other','A detailed concern for book four.');
SELECT public.report_expect_error($q$SELECT public.book_reports_v2_submit(gen_random_uuid(),'book-5','other','A detailed concern for book five.')$q$,'reporting limit');
RESET ROLE;
CREATE TEMP TABLE report_counts AS SELECT (SELECT count(*) FROM public.book_reports_v2) AS reports,(SELECT count(*) FROM public.book_report_events_v2) AS events;
\ir ../../../supabase/live-site/supabase-book-reports-v2.sql
SELECT public.report_test_assert((SELECT count(*) FROM public.book_reports_v2)=(SELECT reports FROM report_counts),'rerun preserves reports');
SELECT public.report_test_assert((SELECT count(*) FROM public.book_report_events_v2)=(SELECT events FROM report_counts),'rerun preserves review history');
SELECT public.report_test_assert(EXISTS(SELECT 1 FROM public.unrelated_data WHERE id='preserve-me'),'unrelated data untouched');
SELECT public.report_test_assert(NOT EXISTS(SELECT 1 FROM public.book_reports_v2 WHERE book_id IN ('draft','hidden')),'no reports against unavailable books');
SELECT 'Book report database checks passed';
